   <div className="ov-stat campus-sections"><span className="campus-stat-icon"><Layers3 size={17}/></span><span>{t('Sections analyzed','الشعب المحللة')}</span><strong><CountUp value={stats.sections}/></strong><span>{t('Current scenario','السيناريو الحالي')}</span></div>
