 {user.role==='professor'&&<MyClasses sid={sid} ar={ar} days={days} revision={data.revision} courseName={courseName} onProposal={p=>{void refresh();setNotice(t('Saved as a request for committee review. You can follow it in My requests.','حُفظ كطلب لمراجعة اللجنة. يمكنك متابعته في «طلباتي».'))}} onOpen={p=>void openProposal(p)}/>}
