  {(tool==='slots'||(!staff&&tool==='edugate'))&&<FreeSlotFinder key={`slots-${sid}`} sid={sid} ar={ar} days={days} role={user.role} sections={data.sections||[]} courseName={courseName} profName={profName} onRequest={user.role==='chair'?undefined:(sectionId,mi,day,start)=>{setHandoff({sectionId,mi,day,start});go('changes')}}/>}
